WITH customer_totals AS (SELECT customer_id, COUNT(CASE WHEN device = 'desktop' THEN 1 END) AS desktop_count, MIN(started_at) AS first_started_at FROM sessions WHERE TO_DATE(started_at) < '2025-05-02' GROUP BY customer_id) SELECT customers.id, customers.city, customer_totals.desktop_count, customer_totals.first_started_at FROM customers INNER JOIN customer_totals ON customers.id = customer_totals.customer_id WHERE customer_totals.desktop_count >= 6 ORDER BY customers.city;
